#!/bin/sh
# Reruns every check of NOTES.md, one Python process at a time (each well under 0.5 GB), and prints PASS/FAIL.
# Total about 2 minutes.  conditions.pkl is regenerated by build_conditions.py.
cd "$(dirname "$0")"
mkdir -p logs
: > logs/run_all.log
fail=0
run() {
  name=$1; shift
  start=$(date +%s)
  python -u ${name}.py "$@" > logs/${name}.log 2>&1
  last=$(tail -n 1 logs/${name}.log)
  end=$(date +%s)
  echo "$name: $last ($((end - start)) s)" | tee -a logs/run_all.log
  [ "$last" = "PASS" ] || fail=1
}
run test_bern            # Bernstein module unit tests (copy of the u = 1 module)
run check_cf             # closed form cf.py = Lemma B builder (exact) and = direct construction (float)
run check_struct         # (S1)-(S4) of Part A of NOTES.md, exactly
run check_cu_form        # (C_u) closed form = principal block on {P_rh: r,h in U} u {Q}; formulas (F1)-(F3), exact
run check_hardpart       # the scalar lemma behind Lemma H, Lemma A constant
run check_blocks         # Phi1 = block formulas (exact) and F(X) >= sigma Phi1 at random points (exact)
run check_bounds_valid   # every per-coordinate bound and auxiliary inequality at 200 configurations (exact)
run check_chain          # Phi1 - (1-t) diag(per-coordinate margins) is PSD, exact LDL at 32 points
run check_points         # (C_u) principal block: exact LDL pivots positive at 33 rational configurations
run build_conditions     # the conditions (I), (II), (III) as rational functions -> conditions.pkl
run prove_conditions     # Bernstein certificates of (I), (II), (III) (exact integer arithmetic)
run controls             # negative controls: tau = 7/10, tau = 2, Q + 1/100 must fail
run sanity_cu            # float sanity sweep (no claim rests on it)
run check_soft           # Part A: exact Rayleigh value of the soft modes Psi_a
run sweep                # Part A: numerical evidence for (C_u), (A_u), (B_u) (no claim rests on it)
if [ $fail -eq 0 ]; then echo "ALL PASS" | tee -a logs/run_all.log; else echo "SOME FAIL" | tee -a logs/run_all.log; fi
